import React, { HTMLAttributes } from 'react';

import X from '@pohodnik/icons/svg/Signs/X';
import clsx from 'clsx';

import { IWorkoutTag } from '@apps/Workouts/@types/workouts.types';

interface IWorkoutTagProps extends HTMLAttributes<HTMLSpanElement> {
  tag: IWorkoutTag;
  onDelete?: () => void;
}

const WorkoutTag: React.FC<IWorkoutTagProps> = ({ tag, onDelete, ...rest }) => {
  return (
    <small
      className={clsx('p-1 me-1 d-inline-flex align-items-center', rest.className)}
      style={{
        background: `#${tag.color}`,
        lineHeight: 1,
        borderRadius: 4,
        fontSize: 8,
        ...(rest.style ?? {}),
      }}
      {...rest}
    >
      {tag.name}
      {onDelete && (
        <button className="p-0 border-0 ms-1 rounded-circle" onClick={onDelete}>
          <X />
        </button>
      )}
    </small>
  );
};

export default WorkoutTag;
